import{s}from"/dist/chunk-6k8ey1xy.js";function n(){return s("div",{class:"markdown-body",dangerouslySetInnerHTML:{__html:`<h1>npm 小技巧</h1><h2>binary_host</h2><p>npm 支持为每个需要 binary 的包指定下载地址。所谓的 binary 是指基于 napi 开发的模块，通过使用 c/c++ 实现，后续一般是 <code>.node</code>。</p><p>例如有一个包 <code>better-sqlite3</code>，那么它需要的二进制文件下载可以通过 <code>&lt;包名&gt;_binary_host</code> 环境变量来指定。<code>better-sqlite3</code> 的 binary_host 应该是 <code>better-sqlite3_binary_host</code>。虽说是环境变量，也可以直接写在 <code>.npmrc</code> 中，全局或当前仓库也可以。我通常使用本地仓库的 <code>.npmrc</code>，这样不会污染全局的配置。</p><p>另外，这个 binary_host 是通过 http/https 访问，因此也可以使用 ghproxy.com 的代理地址。比如上面的 <code>better-sqlite3_binary_host</code>，可以设置为：</p><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">better-sqlite3_binary_host</span><span style="color:#F97583">=</span><span style="color:#9ECBFF">https://ghproxy.com/https://github.com/WiseLibs/better-sqlite3/releases/download</span></span>
<span class="line"><span style="color:#E1E4E8">npm_config_better_sqlite3_binary_host</span><span style="color:#F97583">=</span><span style="color:#9ECBFF">https://ghproxy.com/https://github.com/WiseLibs/better-sqlite3/releases/download</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D"># 如果通过指定 tag，可以使用下面这种形式：</span></span>
<span class="line"><span style="color:#B392F0">uWebSockets.js_binary_host</span><span style="color:#9ECBFF">=https://ghproxy.com/https://github.com/uNetworking/uWebSockets.js/tree/v20.10.0</span></span>
<span class="line"></span></code></pre><p>安装 .node 模块一般是通过 prebuild-install 包实现，在 <code>prebuild-install@^7.0.0</code> 按照下面的函数生成环境变量名：</p><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#6A737D">// node_modules/prebuild-install/util.js</span></span>
<span class="line"><span style="color:#F97583">function</span><span style="color:#B392F0"> getEnvPrefix</span><span style="color:#E1E4E8">(</span><span style="color:#FFAB70">pkgName</span><span style="color:#E1E4E8">) {</span></span>
<span class="line"><span style="color:#F97583">  return</span><span style="color:#9ECBFF"> 'npm_config_'</span><span style="color:#F97583"> +</span><span style="color:#E1E4E8"> (pkgName </span><span style="color:#F97583">||</span><span style="color:#9ECBFF"> ''</span><span style="color:#E1E4E8">).</span><span style="color:#B392F0">replace</span><span style="color:#E1E4E8">(</span><span style="color:#9ECBFF">/</span><span style="color:#79B8FF">[</span><span style="color:#F97583">^</span><span style="color:#79B8FF">a-zA-Z0-9]</span><span style="color:#9ECBFF">/</span><span style="color:#F97583">g</span><span style="color:#E1E4E8">, </span><span style="color:#9ECBFF">'_'</span><span style="color:#E1E4E8">).</span><span style="color:#B392F0">replace</span><span style="color:#E1E4E8">(</span><span style="color:#9ECBFF">/</span><span style="color:#F97583">^</span><span style="color:#DBEDFF">_</span><span style="color:#9ECBFF">/</span><span style="color:#E1E4E8">, </span><span style="color:#9ECBFF">''</span><span style="color:#E1E4E8">);</span></span>
<span class="line"><span style="color:#E1E4E8">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583">function</span><span style="color:#B392F0"> getHostMirrorUrl</span><span style="color:#E1E4E8">(</span><span style="color:#FFAB70">opts</span><span style="color:#E1E4E8">) {</span></span>
<span class="line"><span style="color:#F97583">  const</span><span style="color:#79B8FF"> propName</span><span style="color:#F97583"> =</span><span style="color:#B392F0"> getEnvPrefix</span><span style="color:#E1E4E8">(opts.pkg.name) </span><span style="color:#F97583">+</span><span style="color:#9ECBFF"> '_binary_host'</span><span style="color:#E1E4E8">;</span></span>
<span class="line"><span style="color:#F97583">  return</span><span style="color:#E1E4E8"> process.env[propName] </span><span style="color:#F97583">||</span><span style="color:#E1E4E8"> process.env[propName </span><span style="color:#F97583">+</span><span style="color:#9ECBFF"> '_mirror'</span><span style="color:#E1E4E8">];</span></span>
<span class="line"><span style="color:#E1E4E8">}</span></span>
<span class="line"></span></code></pre><p>有一点需要补充。如果 npm 包官方已经提供的环境变更用于下载 <code>.node</code> 文件。应该按照官方的说明操作。</p><h2>git+https 包地址</h2><p>有一些包，只发布到 github。因为需要使用 github 为下载地址。比如 <code>uWebSockets.js</code>，为其官方的说明，npm install 实现是增加了一个 github 地址。考虑到国内的网络环境。可以使用 <code>git+https</code> 来代替：</p><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">{</span></span>
<span class="line"><span style="color:#6A737D">  // ...</span></span>
<span class="line"><span style="color:#9ECBFF">  "dependencies"</span><span style="color:#E1E4E8">: {</span></span>
<span class="line"><span style="color:#9ECBFF">    "uWebSockets.js"</span><span style="color:#E1E4E8">: </span><span style="color:#9ECBFF">"git+https://ghproxy.com/https://github.com/uNetworking/uWebSockets.js#v20.10.0"</span></span>
<span class="line"><span style="color:#6A737D">    // ...</span></span>
<span class="line"><span style="color:#E1E4E8">  }</span></span>
<span class="line"><span style="color:#E1E4E8">}</span></span>
<span class="line"></span></code></pre><hr /><p>2022 年 10 月 03 日</p>`}},void 0,!1,void 0,this)}export{n as default};
